INSERT INTO panel_option_dict (option_id, cach_dung) VALUES
(0, 'Công dụng: cộng thẳng sức đánh cơ bản (NPoint.addOption case 0: dameAdd += param). Cách dùng: param = số SĐ cộng thêm, thường 500-20000. Điều kiện: trang bị đang mặc, Card hoặc Cung Mệnh.'),
(1, 'Công dụng: thời gian hiệu lực theo phút; server cộng dồn param của option 1 khi gộp 2 vật phẩm trùng template vào hành trang (InventoryService.isItemIncrementalOption). Cách dùng: param = số phút. Điều kiện: vật phẩm cộng dồn kiểu tự luyện tập/bí kiếp.'),
(2, 'Công dụng: cộng HP và KI (NPoint case 2: hp/mp += param x1000). Cách dùng: param theo nghìn, vd 50 = +50.000 HP và +50.000 KI. Điều kiện: trang bị đang mặc.'),
(3, 'Công dụng: vô hiệu một phần sát thương chưởng và chuyển thành KI (NPoint case 3: voHieuChuong += param). Cách dùng: param = % sát thương chưởng được vô hiệu/chuyển KI. Điều kiện: trang bị đang mặc.'),
(4, 'Công dụng: hồi % KI mỗi lần bị đánh trúng (xử lý lúc chịu sát thương). Cách dùng: param = % KI hồi. Điều kiện: trang bị đang mặc; không nằm trong NPoint.addOption.'),
(5, 'Công dụng: tăng % sức đánh chí mạng (NPoint case 5: tlDameCrit và tlSDCM += param). Cách dùng: param = % STCM, thường 1-100. Điều kiện: trang bị đang mặc/Card/Cung Mệnh.'),
(6, 'Công dụng: cộng HP sinh lực (NPoint case 6: hpAdd += param). Cách dùng: param = số HP cộng thêm. Điều kiện: trang bị đang mặc.'),
(7, 'Công dụng: cộng KI (NPoint case 7: mpAdd += param). Cách dùng: param = số KI cộng thêm. Điều kiện: trang bị đang mặc.'),
(8, 'Công dụng: hút % HP và KI của người xung quanh mỗi 5 giây (NPoint case 8: tlHutHpMpXQ). Cách dùng: param = % hút. Điều kiện: trang bị đang mặc, tự động chu kỳ 5 giây.'),
(9, 'Công dụng: đánh dấu thời gian hiệu lực; server dùng param lớn hơn 0 làm cờ đang hiệu lực (vd giáp tập luyện type 32: NPoint.setDameTrainArmor cộng % SĐ theo getPercentTrainArmor). Cách dùng: param = số phút, lớn hơn 0 = còn hiệu lực.'),
(10, 'Ghi chú: option 10 không còn trong NPoint.addOption - chủ yếu hiển thị trên client. Muốn cộng chính xác thật hãy dùng option 18 (tlchinhxac). Cách dùng: param = điểm chính xác hiển thị.'),
(11, 'Công dụng: đánh dấu số Công Đức trên vật phẩm (điểm thưởng dùng cho NPC/shop Công Đức). Cách dùng: param = số công đức. Điều kiện: hiển thị, không cộng chỉ số trực tiếp.'),
(12, 'Công dụng: đếm số lần sử dụng còn lại; khi param về 0 vật phẩm bị xóa khỏi hành trang (InventoryService.subParamItemsBag). Cách dùng: param = số lần. Điều kiện: vật phẩm tiêu hao.'),
(13, 'Công dụng: thống kê số yêu quái đã hạ gắn trên vật phẩm (nhiệm vụ/sự kiện). Cách dùng: param = số quái đã hạ. Điều kiện: hiển thị, không cộng chỉ số.'),
(14, 'Công dụng: cộng % chí mạng (NPoint case 14: critAdd += param). Cách dùng: param = % chí mạng, khuyến nghị 1-25. Điều kiện: trang bị đang mặc.'),
(15, 'Ghi chú: không có trong NPoint.addOption - chủ yếu hiển thị. Phản đòn cận chiến thật dùng option 97 (tlPST). Cách dùng: param = số/% phản đòn hiển thị.'),
(16, 'Công dụng: tăng tốc độ di chuyển (NPoint case 16: tlSpeed += param; speed = 6 + 6 x tlSpeed/100). Cách dùng: param = %, cứ mỗi 100 cộng thêm thì chạy nhanh hơn 1 cấp. Điều kiện: trang bị đang mặc.'),
(17, 'Ghi chú: không có trong NPoint.addOption - hiển thị. Né đòn thật dùng option 108 (tlNeDon). Cách dùng: param = điểm né đòn hiển thị.'),
(18, 'Công dụng: cộng % chính xác (NPoint case 18: tlchinhxac += param). Cách dùng: param = % chính xác. Điều kiện: trang bị đang mặc.'),
(19, 'Công dụng: cộng % tấn công thêm khi đánh quái (NPoint case 19: tlDameAttMob). Cách dùng: param = %, cộng dồn nhiều item. Điều kiện: chỉ áp dụng khi đánh quái, không áp khi đánh người.'),
(20, 'Công dụng: hiển thị PIN của vật phẩm cần năng lượng (vd vệ tinh/phụ kiện). Cách dùng: param = lượng PIN còn lại. Điều kiện: hiển thị, không cộng chỉ số.'),
(21, 'Công dụng: yêu cầu sức mạnh khi mặc (InventoryService: powerRequire = param x 1.000.000.000). Cách dùng: param tính theo TỈ, vd 18 = yêu cầu 18 tỉ SM. Điều kiện: sức mạnh chưa đủ thì không mặc được; SetClothes: param = 80 được đếm vào set ĐHĐ.'),
(22, 'Công dụng: cộng HP (NPoint case 22: hpAdd += param x1000). Cách dùng: param theo NGHÌN, vd 500 = +500.000 HP. Điều kiện: trang bị đang mặc; option ĐƯỢC NÂNG CẤP (InventoryService.optionCanUpgrade).'),
(23, 'Công dụng: cộng KI (NPoint case 23: mpAdd += param x1000). Cách dùng: param theo NGHÌN. Điều kiện: trang bị đang mặc; option ĐƯỢC NÂNG CẤP (optionCanUpgrade).'),
(24, 'Công dụng: cờ hiệu ứng - tăng trọng lực, làm chậm mọi người xung quanh (NPoint case 24: isLamCham). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm có hiệu ứng này.'),
(25, 'Công dụng: cờ hiệu ứng - tàng hình mỗi 5 giây (NPoint case 25: isTanHinh). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm.'),
(26, 'Công dụng: cờ hiệu ứng - hóa đá người xung quanh mỗi 30 giây (NPoint case 26: isHoaDa). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm.'),
(27, 'Công dụng: hồi HP định kỳ (NPoint case 27: hpHoiAdd; nhận mỗi 30 giây). Cách dùng: param = số HP hồi thêm mỗi 30s. Điều kiện: mặc; option ĐƯỢC NÂNG CẤP (optionCanUpgrade).'),
(28, 'Công dụng: hồi KI định kỳ (NPoint case 28: mpHoiAdd; nhận mỗi 30 giây). Cách dùng: param = số KI hồi thêm mỗi 30s. Điều kiện: mặc; option ĐƯỢC NÂNG CẤP (optionCanUpgrade).'),
(29, 'Công dụng: hiệu ứng - biến người xung quanh thành Sôcôla mỗi 30 giây (sự kiện). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm sự kiện.'),
(30, 'Công dụng: cờ Đã khóa - vật phẩm có option 30 (hoặc 218) KHÔNG giao dịch được (Trade.java). Cách dùng: param 1. Điều kiện: làm cờ khóa đồ; nhiều event gán 30 để chặn giao dịch.'),
(31, 'Công dụng: số lượng cộng dồn - server gộp param khi xếp chồng item trùng template (isItemIncrementalOption, vd bí kiếp). Cách dùng: param = số lượng. Điều kiện: gộp item cùng loại vào hành trang.'),
(32, 'Công dụng: cờ miễn nhiễm - người mang không bị hóa Xương (sự kiện). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm có option.'),
(33, 'Công dụng: cờ dịch chuyển tức thời - NPoint case 33: teleport = true khi mặc. Cách dùng: param 0/1. Điều kiện: mặc vật phẩm được bật cờ dịch chuyển.'),
(34, 'Công dụng: đếm mảnh Tinh An - NPoint: đủ 5 món (setTinhAn >= 5) bật hiệu ứng Tinh An. Cách dùng: param 0/1, mỗi món đếm 1 lần. Điều kiện: mặc đủ 5 món có option này.'),
(35, 'Công dụng: đếm mảnh Nguyệt An - đủ 5 món (setNguyetAn >= 5) bật hiệu ứng Nguyệt An. Cách dùng: param 0/1. Điều kiện: mặc đủ 5 món.'),
(36, 'Công dụng: đếm mảnh Nhật An - đủ 5 món (setNhatAn >= 5) bật hiệu ứng Nhật An. Cách dùng: param 0/1. Điều kiện: mặc đủ 5 món.'),
(37, 'Công dụng: thống kê số lần đã ký gửi của vật phẩm (type 4). Cách dùng: param = số lần ký gửi. Điều kiện: hiển thị, không cộng chỉ số.'),
(38, 'Công dụng: option điều kiện - chỉ phát huy tác dụng khi người chơi đang HỢP THỂ. Cách dùng: param 0/1. Điều kiện: đang hợp thể (fusion).'),
(39, 'Công dụng: hiển thị % bạo kích sức đánh chưởng (STCM). Cách dùng: param = % bạo kích. Điều kiện: type 6; cộng chí mạng thật server dùng option 5/14 - kiểm tra param hợp lý trước khi cấp.'),
(40, 'Công dụng: đánh dấu số đá ngũ sắc đã nạp cho Siêu Cải Trang (tiêu chí nâng siêu cải trang). Cách dùng: param = số đá. Điều kiện: dùng trên cải trang, hiển thị/điều kiện nâng.'),
(41, 'Công dụng: nhãn Chỉ số thưởng - hiển thị chỉ số thưởng thêm của vật phẩm (khảm đá/set). Cách dùng: param = giá trị thưởng. Điều kiện: hiển thị, không cộng riêng trong NPoint.'),
(42, 'Công dụng: nhãn % Khảm Đá cho Sức Đánh. Cách dùng: param = % sau khảm. Ghi chú: case 42-46 trong NPoint.addOption đang bị comment - server không cộng thẳng, chỉ hiển thị.'),
(43, 'Công dụng: nhãn % Khảm Đá cho HP. Cách dùng: param = %. Ghi chú: NPoint case 43 đang comment - không cộng thẳng.'),
(44, 'Công dụng: nhãn % Khảm Đá cho KI. Cách dùng: param = %. Ghi chú: NPoint case 44 đang comment - không cộng thẳng.'),
(45, 'Công dụng: nhãn % Khảm Đá cho GIÁP. Cách dùng: param = %. Ghi chú: NPoint case 45 đang comment - không cộng thẳng.'),
(46, 'Công dụng: nhãn % Khảm Đá cho Bạo Kích. Cách dùng: param = %. Ghi chú: NPoint case 46 đang comment - không cộng thẳng.'),
(47, 'Công dụng: cộng giáp/DEF (NPoint case 47: defAdd += param). Cách dùng: param = số giáp cộng thêm, thường 100-5000. Điều kiện: mặc; option ĐƯỢC NÂNG CẤP (optionCanUpgrade).'),
(48, 'Công dụng: cộng cả HP và KI (NPoint case 48: hpAdd và mpAdd += param, đơn vị thường). Cách dùng: param = số HP và KI cộng thêm. Điều kiện: mặc.'),
(49, 'Công dụng: tăng % sức đánh (NPoint case 49/50: tlDame += param x opt49_factor/100, hệ số mặc định 10). Cách dùng: param = % theo tên; server thực nhận khoảng param chia 10 (% SĐ) - test trước khi cấp lớn. Điều kiện: mặc.'),
(50, 'Công dụng: tăng % sức đánh (NPoint case 50: tlDame += param x opt49_factor/100, mặc định 10). Cách dùng: param = %; thực nhận khoảng param chia 10 (% SĐ). Điều kiện: mặc/Card/Cung Mệnh.'),
(51, 'Công dụng: bộ Sét Broly - SetClothes đếm option trên 5 slot đầu, đủ 5/5 kích hoạt +25% Giảm ST (theo tên). Cách dùng: param 0/1/món, trùng trong 1 món chỉ đếm 1. Điều kiện: mặc đủ 5/5.'),
(52, 'Công dụng: bộ Sét Picolo - +500% KI khi đủ 5/5 (SetClothes.setpicolo). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5 trên 5 slot đầu.'),
(53, 'Công dụng: bộ Sét Vegeta - +500% HP khi đủ 5/5 (SetClothes.setvegeta). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5.'),
(54, 'Công dụng: bộ Sét Goku - +80% SD khi đủ 5/5 (SetClothes.setgoku). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5.'),
(55, 'Công dụng: bộ Sét Phụ Hồ - +8888% TNSM khi đủ 5/5 (SetClothes.setphuho). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5.'),
(56, 'Công dụng: bộ Sét Mabu - +25% Chí Mạng khi đủ 5/5 (SetClothes.setmabu). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5.'),
(57, 'Công dụng: option bộ Đường Tăng - SetClothes.setduongtang++ khi đủ 5/5. Cách dùng: param 0/1/món. Điều kiện: đủ 5/5. LƯU Ý: tên option đang TRỐNG trong DB, nên cập nhật NAME để hiển thị đúng.'),
(58, 'Công dụng: option bộ Đường Tăng SS - SetClothes.setduongtangss++ khi đủ 5/5. Cách dùng: param 0/1/món. Điều kiện: đủ 5/5. LƯU Ý: tên option đang TRỐNG trong DB.'),
(59, 'Công dụng: nhãn Thuộc Tính Cơ Bản - đánh dấu nhóm thuộc tính cơ bản (vd nhẫn cưới sự kiện EventKetHon). Cách dùng: param 1-2. Điều kiện: hiển thị nhóm, không cộng chỉ số.'),
(60, 'Công dụng: nhãn Thuộc Tính Bộ - đánh dấu nhóm thuộc tính bộ. Cách dùng: param 1-2. Điều kiện: hiển thị.'),
(61, 'Công dụng: nhãn Thuộc Tính Phụ - đánh dấu nhóm thuộc tính phụ. Cách dùng: param 1-2. Điều kiện: hiển thị.'),
(62, 'Công dụng: phục hồi thể lực theo % (item phục hồi stamina). Cách dùng: param = % thể lực hồi. Điều kiện: dùng/mặc theo vật phẩm; không nằm trong NPoint.addOption.'),
(63, 'Công dụng: hiển thị HSD còn lại theo NGÀY (đếm ngược client). Cách dùng: param = số ngày. Điều kiện: vật phẩm có hạn.'),
(64, 'Công dụng: hiển thị HSD còn lại theo GIỜ. Cách dùng: param = số giờ. Điều kiện: vật phẩm có hạn.'),
(65, 'Công dụng: hiển thị HSD còn lại theo PHÚT. Cách dùng: param = số phút. Điều kiện: vật phẩm có hạn.'),
(66, 'Công dụng: bộ Sét Dragon - +1500% SĐ khi đủ 5/5 (SetClothes.setsaga). Cách dùng: param 0/1/món. Điều kiện: đủ 5/5 trên 5 slot đầu.'),
(67, 'Công dụng: đánh dấu vật phẩm Sự Kiện Đi Biển (EventKetHon gán lên nhẫn cưới). Cách dùng: param 0/1. Điều kiện: vật phẩm sự kiện, không cộng chỉ số.'),
(68, 'Công dụng: đánh dấu Linh Khí (bậc khí giới 1). Cách dùng: param 0/1 hoặc bậc. Điều kiện: hiển thị bậc, điều kiện nâng bậc khí giới.'),
(69, 'Công dụng: đánh dấu Tiên Khí (bậc khí giới 2). Cách dùng: param như LINH KHÍ. Điều kiện: điều kiện nâng bậc.'),
(70, 'Công dụng: đánh dấu Đế Khí (bậc khí giới 3). Cách dùng: param như trên. Điều kiện: điều kiện nâng bậc.'),
(71, 'Công dụng: đánh dấu Thánh Khí (bậc khí giới cao nhất). Cách dùng: param như trên. Điều kiện: điều kiện nâng bậc.'),
(72, 'Công dụng: Cấp độ vật phẩm (boss/rương random 1-16 theo Util.randDoTL). Cách dùng: param = cấp, vd 1-16. Điều kiện: hiển thị cấp để so sánh/nâng cấp.'),
(73, 'Công dụng: watermark DragonBallSaga.vn; server DÙNG option này (param 0) làm option rỗng mặc định cho item không có option (InventoryService.addItemList). Cách dùng: param 0. Điều kiện: tự động thêm khi item chưa có option.'),
(74, 'Công dụng: đánh dấu vật phẩm Đã ép (đã ép/phúc hợp trang bị). Cách dùng: param 0/1. Điều kiện: hiển thị, điều kiện nâng cấp.'),
(75, 'Công dụng: đánh dấu bộ Đã Kích Hoạt (Util gán 75 param 1 khi sinh đồ - cờ set kích hoạt). Cách dùng: param 1. Điều kiện: vật phẩm đã kích hoạt.'),
(76, 'Công dụng: cờ VIP trên vật phẩm. Cách dùng: param = mức VIP hoặc 1. Điều kiện: chỉ vật phẩm VIP; hiển thị/điều kiện sử dụng.'),
(77, 'Công dụng: tăng % HP tối đa (NPoint case 77: tlHp += param x opt77_factor/100, hệ số mặc định 10). Cách dùng: param = % theo tên option; server quy đổi qua hệ số - test param thực tế. Điều kiện: mặc.'),
(78, 'Công dụng: hiển thị % Sức Hủy Diệt theo tên option. Ghi chú: không có trong NPoint.addOption - chủ yếu nhãn hiển thị; dame thật dùng option 50/147/239. Cách dùng: param = % hiển thị.'),
(79, 'Công dụng: +% sức đánh cho ĐỆ TỬ (pet) khi sư phụ mặc. Cách dùng: param = %. Điều kiện: có đệ tử; không nằm trong NPoint.addOption của người chơi (xem hệ thống pet).'),
(80, 'Công dụng: hồi % HP mỗi 30 giây (NPoint case 80: tlHpHoi += param, giới hạn 100). Cách dùng: param = % HP hồi mỗi 30s. Điều kiện: mặc; không vượt 100.'),
(81, 'Công dụng: hồi % KI mỗi 30 giây (NPoint case 81: tlMpHoi, giới hạn 100). Cách dùng: param = % KI hồi mỗi 30s. Điều kiện: mặc.'),
(82, 'Công dụng: passive - không bị quái chủ động đánh và giảm 20% sát thương khi bị đánh (theo tên). Cách dùng: param 0/1. Điều kiện: mặc; không cộng qua NPoint.addOption.'),
(83, 'Công dụng: passive - tăng 20% sức mạnh và tiềm năng nhận được khi đánh quái (theo tên). Cách dùng: param 0/1. Điều kiện: mặc; không nằm trong NPoint.addOption.'),
(84, 'Công dụng: bay không tốn KI (theo tên). Cách dùng: param 0/1. Điều kiện: mặc vật phẩm bay/cánh, hiệu ứng áp khi nhân vật bay.'),
